import{_ as s,o as e,c as p,ai as l}from"./chunks/framework.DAbPic9L.js";const x=JSON.parse('{"title":"易数术-六爻八卦","description":"","frontmatter":{},"headers":[],"relativePath":"mybook/yi-shu-shu/liu-yao-ba-gua.md","filePath":"mybook/yi-shu-shu/liu-yao-ba-gua.md","lastUpdated":1787215730000}'),t={name:"mybook/yi-shu-shu/liu-yao-ba-gua.md"};function n(i,a,r,c,d,o){return e(),p("div",null,[...a[0]||(a[0]=[l('<h1 id="易数术-六爻八卦" tabindex="-1">易数术-六爻八卦 <a class="header-anchor" href="#易数术-六爻八卦" aria-label="Permalink to &quot;易数术-六爻八卦&quot;">​</a></h1><p>文/晨风不可依米</p><br><p>时代的更迭千古不变，宇宙的演化从一而终；因此，由易初始，由易而终。</p><p>所谓易，即是变易、不易、简易三性特征的统称。</p><p><span class="text-red">变易</span>的体现在于万事万物的<span class="text-red">象</span>随时变化，<span class="text-red">易在机锋</span>。</p><p><span class="text-red">不易</span>的体现在于自然规律的<span class="text-red">性</span>亘古不变，<span class="text-red">易在神性</span>。</p><p><span class="text-red">简易</span>的体现在于真理大道的<span class="text-red">解</span>化繁为简，<span class="text-red">易在明性</span>。</p><br><p>然而，现代人在这个快节奏的逐利时代，早已失去淳朴易观。</p><p>朝代更迭，官史扭曲，甚少如实记录。</p><p>文化传播，词意盲创，古今通义断层。</p><p>人性使然，喜闻乐见，世学无以后继。</p><p>因此，导致&quot;<span class="text-red">前贤思其义，而子传其言；后世诵读者，秦后少真义</span>&quot;的现象。</p><p>现代人学易，多是手捧经书，脑背卦辞；可概括为“<span class="text-red">今人得其辞，而未达其意（神性）</span>”。</p><br><p>个人学易观点：<span class="text-red">君子静则以观物，以悟其辞；动则观变，以筮其占。象图性解，心领神悟；机不可失，失不再来，难在机锋成象的精准把控，难在象图性解的深刻领悟。学易的过程是遵循“观天之道，执天之行”的求索考证过程。事所发有所兆，其中蕴含吉凶消长之道，进退存亡之道</span>。</p><br><p><strong>学易注意事项</strong></p><ul><li>术业有专攻（专人做专事），小知不及大知（领域知识无法抗衡广博知识）。</li><li>大知为根，小知是叶，即大道和小道的关系；切记以叶为道，容易蒙蔽。</li><li>正确的理论，没有例外；行为做法于事无补，将陷入形的困局。知行合一，用神如助。</li><li>不要拿身段讲权威，容易陷入无知或小知的深渊里。求知海纳百川，考证学而后思。</li><li>万事万物先了解，再决情断疑，后决定否定；否则不知而说，这是无知行为。</li></ul><h2 id="六爻八卦" tabindex="-1">六爻八卦 <a class="header-anchor" href="#六爻八卦" aria-label="Permalink to &quot;六爻八卦&quot;">​</a></h2><h3 id="六爻符号" tabindex="-1">六爻符号 <a class="header-anchor" href="#六爻符号" aria-label="Permalink to &quot;六爻符号&quot;">​</a></h3><ul><li><p>表现形式：六个爻，有阴爻(<code>- -</code>)、阳爻（<code>---</code>）之分。</p></li><li><p>顺序明解：摇爻出筒，从上而下；确爻顺序，从下而上，即初、二、三、四、五、上等爻序，代表事物发展的每个阶段（<code>下将相宰君过</code>）。</p></li><li><p>三爻组卦：初、二、三等爻构成内卦，为本；四、五、上等爻构成外卦，为位。有内本外位之分。卦代表事情，爻代表时机。</p></li><li><p>爻卦术语</p><ul><li>三阳为乾，表父；口诀为乾三连(<code>☰</code>)。</li><li>三阴为坤，表母；口诀为坤六段(<code>☷</code>)。</li><li>一阳在下为震，表长子；口诀为震仰盂(<code>☳</code>)。</li><li>一阳在中为坎，表次男；口诀为坎中满(<code>☵</code>)。</li><li>一阳在上为艮，表少男；口诀为艮覆碗(<code>☶</code>)。</li><li>一阴在下为巽，表长女；口诀为巽下断(<code>☴</code>)。</li><li>一阴在中为离，表次女；口诀为离中虚(<code>☲</code>)。</li><li>一阴在上为兑，表少女；口诀为兑上缺(<code>☱</code>)。</li></ul></li><li><p>爻卦神性</p><ul><li>乾卦：天也，刚健。坚心至刚。至高往下看，始终如一；天无立法，天威自显。</li><li>坤卦：地也，柔顺。坤德柔顺。无所求所怨，始终如一；人之至诚，行事无悔。</li><li>兑卦：泽也，悦象。以和为贵。外交处事，君子悦外健内柔，小人悦皮笑肉不笑。</li><li>离卦：火也，中虚。外明内虚。大过凶，小不及；不大不小，取中庸之道。</li><li>震卦：雷也，主动。声闻百里。（时机）不动则已，一动惊世。</li><li>巽卦：风也，顺入。无孔不入。顺其民心（知而行），投其所好，和风润物。</li><li>坎卦：水也，险陷。行险之道。常位于险中第一线。至诚至刚，坚心可脱险。</li><li>艮卦：山也，止大。进退有道。止之道，目所不见，无欲可退；谦之道，政令有序，稳当可进。</li></ul></li><li><p>起课手法：恍惚之间（必要时机），以筮其占（时机断事）；心无杂念，心诚起课；六摇一排展开，未成一排重摇；象图性解，处机应变。<span class="text-red">禁忌不疑不卜；不抱有侥幸，犯险求结果</span>。</p></li></ul><br><h3 id="先天八卦" tabindex="-1">先天八卦 <a class="header-anchor" href="#先天八卦" aria-label="Permalink to &quot;先天八卦&quot;">​</a></h3><p><span class="text-red">兑泽</span> -- <span class="text-red">乾天</span> -- <span class="text-green">巽风</span></p><p><span class="text-red">离火</span> --- 中 --- <span class="text-green">坎水</span></p><p><span class="text-red">震雷</span> -- <span class="text-green">坤地</span> -- <span class="text-green">艮山</span></p><br><p>先天八卦是伏羲氏所创，以自然界物象为基础，延展体会神性。</p><p>理解顺序，四位左右包抄：<code>乾兑离震</code>，<code>巽坎艮坤</code>。</p><br><h3 id="后天八卦" tabindex="-1">后天八卦 <a class="header-anchor" href="#后天八卦" aria-label="Permalink to &quot;后天八卦&quot;">​</a></h3><p><span class="text-red">巽风</span> -- <span class="text-red">离火</span> -- <span class="text-green">坤地</span></p><p><span class="text-red">震雷</span> --- <span class="text-red">土</span> --- <span class="text-red">兑泽</span></p><p><span class="text-green">艮山</span> -- <span class="text-red">坎水</span> -- <span class="text-red">乾天</span></p><br><p>后天八卦是周文王所创，以自然界规律为基础，洞察万物变化。</p><p>理解顺序，五行生克原理，对角左斜土，<code>M</code>型连线（<code>木火土金水</code>）。</p><p>万物变化有所规律，阶段可明确，结果可预测；学易在于防微杜渐，在于以果决行。</p><p><span class="text-red">历史往复可参考，但自然法则从不变；学易要用神传神，切勿学形解读</span>。</p><br><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h3><p><span class="text-red">天所赋为命，运操之在你</span>。天地亘古不变，故应顺天承运；自然规律有术，故应观天而行。</p><ul><li><p>批八字：论命指引，十年大限；科权禄忌，待机而动；吉凶祸福，进退存亡。</p></li><li><p>阳宅学：长幼有序，名位相等。各安其位，（成婚嫁娶）时机补位；因时而变，顺天承运。</p></li><li><p>阴宅学：？。</p></li></ul>',45)])])}const h=s(t,[["render",n]]);export{x as __pageData,h as default};
